// 诗词数据库
const poetryDatabase = [
    {
        title: "静夜思",
        author: "李白",
        dynasty: "唐",
        content: "床前明月光，\n疑是地上霜。\n举头望明月，\n低头思故乡。",
        translation: "明亮的月光洒在床前的窗户纸上，好像地上泛起了一层霜。我禁不住抬起头来，看那天窗外空中的一轮明月，不由得低头沉思，想起远方的家乡。",
        appreciation: "这首诗写的是在寂静的月夜思念家乡的感受。诗的前两句写诗人在作客他乡的特定环境中一刹那间所产生的错觉；后两句写诗人从仰望明月到低头思乡的动作变化，形象地揭示了诗人内心活动。",
        tags: ["思乡", "月夜", "五言绝句"]
    },
    {
        title: "将进酒",
        author: "李白",
        dynasty: "唐",
        content: "君不见，黄河之水天上来，奔流到海不复回。\n君不见，高堂明镜悲白发，朝如青丝暮成雪。\n人生得意须尽欢，莫使金樽空对月。\n天生我材必有用，千金散尽还复来。\n烹羊宰牛且为乐，会须一饮三百杯。\n岑夫子，丹丘生，将进酒，杯莫停。\n与君歌一曲，请君为我倾耳听。\n钟鼓馔玉不足贵，但愿长醉不复醒。\n古来圣贤皆寂寞，惟有饮者留其名。\n陈王昔时宴平乐，斗酒十千恣欢谑。\n主人何为言少钱，径须沽取对君酌。\n五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。",
        translation: "你难道没有看见吗？那黄河之水犹如从天上倾泻而来，波涛滚滚直奔向大海不再回还。你难道没有看见，在高堂上面对明镜，深沉悲叹那一头白发？早晨还是满头青丝，傍晚却变得如雪一般。",
        appreciation: "此诗为李白长安放还以后所作，思想内容非常深沉，艺术表现非常成熟。诗中反复感叹人生短暂，但在感叹中又有强烈的自信。",
        tags: ["饮酒", "人生", "乐府诗"]
    },
    {
        title: "水调歌头·明月几时有",
        author: "苏轼",
        dynasty: "宋",
        content: "明月几时有？把酒问青天。\n不知天上宫阙，今夕是何年。\n我欲乘风归去，又恐琼楼玉宇，高处不胜寒。\n起舞弄清影，何似在人间。\n\n转朱阁，低绮户，照无眠。\n不应有恨，何事长向别时圆？\n人有悲欢离合，月有阴晴圆缺，此事古难全。\n但愿人长久，千里共婵娟。",
        translation: "明月从什么时候才开始出现的？我端起酒杯遥问苍天。不知道在天上的宫殿，今天晚上是何年何月。我想要乘御清风回到天上，又恐怕在美玉砌成的楼宇，受不住高耸九天的寒冷。",
        appreciation: "此词是中秋望月怀人之作，表达了对胞弟苏辙的无限怀念。词人运用形象描绘手法，勾勒出一种皓月当空、美人千里、孤高旷远的境界氛围。",
        tags: ["中秋", "思念", "词"]
    },
    {
        title: "登鹳雀楼",
        author: "王之涣",
        dynasty: "唐",
        content: "白日依山尽，\n黄河入海流。\n欲穷千里目，\n更上一层楼。",
        translation: "夕阳依傍着西山慢慢地沉没，滔滔黄河朝着东海汹涌奔流。若想把千里的风光景物看够，那就要登上更高的一层城楼。",
        appreciation: "此诗前两句写的是自然景色，但开笔就有缩万里于咫尺，使咫尺有万里之势；后两句写意，写的出人意料，把哲理与景物、情势溶化得天衣无缝。",
        tags: ["登高", "哲理", "五言绝句"]
    },
    {
        title: "春晓",
        author: "孟浩然",
        dynasty: "唐",
        content: "春眠不觉晓，\n处处闻啼鸟。\n夜来风雨声，\n花落知多少。",
        translation: "春日里贪睡不知不觉天已破晓，搅乱我酣眠的是那啁啾的小鸟。昨天夜里风声雨声一直不断，那娇美的春花不知被吹落了多少？",
        appreciation: "这首诗是诗人隐居在鹿门山时所做，意境十分优美。诗人抓住春天的早晨刚刚醒来时的一瞬间展开描写和联想，生动地表达了诗人对春天的热爱和怜惜之情。",
        tags: ["春天", "惜春", "五言绝句"]
    },
    {
        title: "念奴娇·赤壁怀古",
        author: "苏轼",
        dynasty: "宋",
        content: "大江东去，浪淘尽，千古风流人物。\n故垒西边，人道是，三国周郎赤壁。\n乱石穿空，惊涛拍岸，卷起千堆雪。\n江山如画，一时多少豪杰。\n\n遥想公瑾当年，小乔初嫁了，雄姿英发。\n羽扇纶巾，谈笑间，樯橹灰飞烟灭。\n故国神游，多情应笑我，早生华发。\n人生如梦，一尊还酹江月。",
        translation: "大江浩浩荡荡向东流去，滔滔巨浪淘尽千古英雄人物。那旧营垒的西边，人们说那就是三国时周瑜鏖战的赤壁。陡峭的石壁直耸云天，如雷的惊涛拍击着江岸，激起的浪花好似卷起千万堆白雪。",
        appreciation: "此词怀古抒情，写自己消磨壮心殆尽，转而以旷达之心关注历史和人生。上片以描写赤壁矶风起浪涌的自然风景为主，意境开阔博大，感慨隐约深沉。",
        tags: ["怀古", "赤壁", "词"]
    },
    {
        title: "望岳",
        author: "杜甫",
        dynasty: "唐",
        content: "岱宗夫如何？齐鲁青未了。\n造化钟神秀，阴阳割昏晓。\n荡胸生曾云，决眦入归鸟。\n会当凌绝顶，一览众山小。",
        translation: "巍峨的泰山，到底如何雄伟？走出齐鲁，依然可见那青青的峰顶。神奇自然汇聚了千种美景，山南山北分隔出清晨和黄昏。层层白云，荡涤胸中沟壑；翩翩归鸟，飞入赏景眼圈。",
        appreciation: '这首诗是杜甫青年时代的作品，充满了诗人青年时代的浪漫与激情。全诗没有一个"望"字，却紧紧围绕诗题"望岳"的"望"字着笔，由远望到近望，再到凝望，最后是俯望。',
        tags: ["登高", "泰山", "五言古诗"]
    },
    {
        title: "相思",
        author: "王维",
        dynasty: "唐",
        content: "红豆生南国，\n春来发几枝。\n愿君多采撷，\n此物最相思。",
        translation: "红豆生长在南方，春天来了它将发出多少新枝呢？希望你多多采摘它，因为它最能够引起人们的思念之情。",
        appreciation: "这是借咏物而寄相思的诗。一题为《江上赠李龟年》，可见是眷怀友人无疑。起句因物起兴，语虽单纯，却富于想象；接着以设问寄语，意味深长。",
        tags: ["相思", "友情", "五言绝句"]
    },
    {
        title: "春望",
        author: "杜甫",
        dynasty: "唐",
        content: "国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。",
        translation: "长安沦陷，国家破碎，只有山河依旧；春天来了，人烟稀少的长安城里草木茂密。感于战败的时局，看到花开而潸然落泪，内心惆怅怨恨，听到鸟鸣而心惊胆战。",
        appreciation: "这首诗反映了诗人热爱国家、眷念家人的美好情操，意脉贯通而不平直，情景兼具而不游离，感情强烈而不浅露，内容丰富而不芜杂，格律严谨而不板滞。",
        tags: ["战争", "思乡", "五言律诗"]
    },
    {
        title: "枫桥夜泊",
        author: "张继",
        dynasty: "唐",
        content: "月落乌啼霜满天，\n江枫渔火对愁眠。\n姑苏城外寒山寺，\n夜半钟声到客船。",
        translation: "月亮已落下乌鸦啼叫寒气满天，江边枫树与船上渔火，难抵我独自傍愁而眠。姑苏城外那寂寞清静寒山古寺，半夜里敲钟的声音传到了客船。",
        appreciation: "这首七绝以一愁字统起。前二句意象密集：落月、啼乌、满天霜、江枫、渔火、不眠人，造成一种意韵浓郁的审美情境。后二句意象疏宕：城、寺、船、钟声，是一种空灵旷远的意境。",
        tags: ["羁旅", "夜景", "七言绝句"]
    },
    {
        title: "江雪",
        author: "柳宗元",
        dynasty: "唐",
        content: "千山鸟飞绝，\n万径人踪灭。\n孤舟蓑笠翁，\n独钓寒江雪。",
        translation: "千山万岭不见飞鸟的踪影，千路万径不见行人的足迹。一叶孤舟上，一位披戴着蓑衣斗笠的渔翁；独自在漫天风雪中垂钓。",
        appreciation: "此诗描绘了一幅渔翁寒江独钓图，表达了诗人永贞革新失败后，虽处境孤独，但仍傲岸不屈、淡泊名利、洁身自好的高洁品质。",
        tags: ["写景", "冬天", "五言绝句"]
    },
    {
        title: "清明",
        author: "杜牧",
        dynasty: "唐",
        content: "清明时节雨纷纷，\n路上行人欲断魂。\n借问酒家何处有？\n牧童遥指杏花村。",
        translation: "清明节这天细雨纷纷，路上远行的人好像断魂一样迷乱凄凉。问一声牧童哪里才有酒家，他指了指远处的杏花小村。",
        appreciation: "此诗写清明春雨中所见。色彩清淡，心境凄冷，历来广为传诵。第一句交代情景、环境、气氛；第二句写出了人物，显示了人物的凄迷纷乱的心境。",
        tags: ["清明", "节日", "七言绝句"]
    },
    {
        title: "出塞",
        author: "王昌龄",
        dynasty: "唐",
        content: "秦时明月汉时关，\n万里长征人未还。\n但使龙城飞将在，\n不教胡马度阴山。",
        translation: "依旧是秦汉时期的明月和边关，守边御敌鏖战万里征人未回还。倘若龙城的飞将李广如今还在，绝不许匈奴南下牧马度过阴山。",
        appreciation: "这是一首慨叹边战不断，国无良将的边塞诗。诗的首句最耐人寻味。说的是此地汉关，明月秦时，大有历史变换，征战未断的感叹。",
        tags: ["边塞", "战争", "七言绝句"]
    },
    {
        title: "送元二使安西",
        author: "王维",
        dynasty: "唐",
        content: "渭城朝雨浥轻尘，\n客舍青青柳色新。\n劝君更尽一杯酒，\n西出阳关无故人。",
        translation: "渭城早晨一场春雨沾湿了轻尘，客舍周围柳树的枝叶翠嫩一新。老朋友请你再干一杯美酒，向西出了阳关就难以遇到故旧亲人。",
        appreciation: "此诗是王维送朋友去西北边疆时作的诗，诗题又名《渭城曲》《阳关曲》《阳关三叠》。前两句写送别的时间、地点和环境气氛。后两句是一个整体，写惜别，先以客观景物作陪衬。",
        tags: ["送别", "友情", "七言绝句"]
    },
    {
        title: "蜀道难",
        author: "李白",
        dynasty: "唐",
        content: "噫吁嚱，危乎高哉！\n蜀道之难，难于上青天！\n蚕丛及鱼凫，开国何茫然！\n尔来四万八千岁，不与秦塞通人烟。\n西当太白有鸟道，可以横绝峨眉巅。\n地崩山摧壮士死，然后天梯石栈相钩连。\n上有六龙回日之高标，下有冲波逆折之回川。\n黄鹤之飞尚不得过，猿猱欲度愁攀援。\n青泥何盘盘，百步九折萦岩峦。\n扪参历井仰胁息，以手抚膺坐长叹。",
        translation: "唉呀呀！多么高峻伟岸！蜀道真太难攀登，简直难于上青天。传说中蚕丛和鱼凫建立了蜀国，开国的年代实在久远无法详谈。自从那时至今约有四万八千年，秦蜀被秦岭所阻从不沟通往返。",
        appreciation: "这首诗袭用乐府旧题，展开丰富的想象，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了对社会的某些忧虑与关切。",
        tags: ["山水", "蜀道", "乐府诗"]
    }
];
let currentDynasty = "all";
function setDynasty(el) {
    document.querySelectorAll(".filter-tag").forEach((tag) => tag.classList.remove("active"));
    el.classList.add("active");
    currentDynasty = el.dataset.dynasty;
    search();
}
function quickSearch(text) {
    document.getElementById("searchInput").value = text;
    search();
}
function handleKeyPress(event) {
    if (event.key === "Enter")
        search();
}
function search() {
    const query = document.getElementById("searchInput").value.trim().toLowerCase();
    const resultSection = document.getElementById("resultSection");
    const resultList = document.getElementById("resultList");
    const resultCount = document.getElementById("resultCount");
    let results = poetryDatabase;
    // 按朝代筛选
    if (currentDynasty !== "all") {
        results = results.filter((poem) => poem.dynasty === currentDynasty);
    }
    // 按关键词搜索
    if (query) {
        results = results.filter((poem) => poem.title.toLowerCase().includes(query) ||
            poem.author.toLowerCase().includes(query) ||
            poem.content.toLowerCase().includes(query));
    }
    resultSection.classList.remove("hidden");
    resultCount.textContent = `找到 ${results.length} 首诗词`;
    resultList.textContent = "";
    if (results.length === 0) {
        const noResult = document.createElement("div");
        noResult.className = "no-result";
        noResult.textContent = "没有找到相关诗词";
        resultList.appendChild(noResult);
        return;
    }
    results.forEach((poem) => {
        const card = createPoemCard(poem);
        resultList.appendChild(card);
    });
}
function createPoemCard(poem) {
    const card = document.createElement("div");
    card.className = "poem-card";
    // 复制按钮
    const copyBtn = document.createElement("button");
    copyBtn.className = "copy-btn";
    copyBtn.textContent = "复制";
    copyBtn.onclick = () => copyPoem(poem, copyBtn);
    card.appendChild(copyBtn);
    // 头部
    const header = document.createElement("div");
    header.className = "poem-header";
    const title = document.createElement("div");
    title.className = "poem-title";
    title.textContent = poem.title;
    const meta = document.createElement("div");
    meta.className = "poem-meta";
    const authorSpan = document.createElement("span");
    authorSpan.textContent = poem.author;
    const dynastySpan = document.createElement("span");
    dynastySpan.textContent = "[" + poem.dynasty + "]";
    meta.appendChild(dynastySpan);
    meta.appendChild(authorSpan);
    header.appendChild(title);
    header.appendChild(meta);
    card.appendChild(header);
    // 正文
    const content = document.createElement("div");
    content.className = "poem-content";
    content.textContent = poem.content;
    card.appendChild(content);
    // 译文
    if (poem.translation) {
        const transSection = document.createElement("div");
        transSection.className = "poem-section";
        const transTitle = document.createElement("div");
        transTitle.className = "section-title";
        transTitle.textContent = "译文";
        const transContent = document.createElement("div");
        transContent.className = "section-content";
        transContent.textContent = poem.translation;
        transSection.appendChild(transTitle);
        transSection.appendChild(transContent);
        card.appendChild(transSection);
    }
    // 赏析
    if (poem.appreciation) {
        const apprSection = document.createElement("div");
        apprSection.className = "poem-section";
        const apprTitle = document.createElement("div");
        apprTitle.className = "section-title";
        apprTitle.textContent = "赏析";
        const apprContent = document.createElement("div");
        apprContent.className = "section-content";
        apprContent.textContent = poem.appreciation;
        apprSection.appendChild(apprTitle);
        apprSection.appendChild(apprContent);
        card.appendChild(apprSection);
    }
    return card;
}
function copyPoem(poem, btn) {
    const text = `${poem.title}\n${poem.dynasty} · ${poem.author}\n\n${poem.content}`;
    navigator.clipboard.writeText(text).then(() => {
        btn.textContent = "已复制";
        setTimeout(() => (btn.textContent = "复制"), 1500);
    });
}
// 初始加载显示所有诗词
search();
// Theme toggle
function toggleTheme() {
    const html = document.documentElement;
    const currentTheme = html.getAttribute("data-theme");
    const newTheme = currentTheme === "light" ? "dark" : "light";
    html.setAttribute("data-theme", newTheme);
    document.getElementById("theme-icon").textContent = newTheme === "light" ? "☀️" : "🌙";
    localStorage.setItem("theme", newTheme);
}
// Load saved theme
const savedTheme = localStorage.getItem("theme") || "dark";
if (savedTheme === "light") {
    document.documentElement.setAttribute("data-theme", "light");
    document.getElementById("theme-icon").textContent = "☀️";
}
